  /// JWT access token for API authentication, valid for 1 hour from issuance.
  access_token String

  /// JWT refresh token for obtaining new access tokens, valid for 7 days from
  /// issuance.
  refresh_token String

  /// Client IP address at session creation for security auditing.
  ip String

  /// Current URL where the user logged in from.
  href String

  /// Referrer URL that led to the login page.
