  TestValidator.predicate(
    "expired_at is valid datetime",
    /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}/.test(
      guest1.token.expired_at,
    ),
  );
  TestValidator.predicate(
    "refreshable_until is valid datetime",
    /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}/.test(
      guest1.token.refreshable_until,
    ),
