import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

/**
 * Test guest session refresh success path.
 * 1. Create initial guest session to obtain valid refresh token
 * 2. Use refresh token to call refresh endpoint
 * 3. Validate new tokens and expiration timestamps are returned
 */
export async function test_api_guest_refresh_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create initial guest session
  const guestConnection: api.IConnection = { host: connection.host };
  const joinResult = await authorize_guest_join(guestConnection, {
    body: {
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(joinResult);
  // 2. Extract refresh token from join response
  const refreshToken = joinResult.token.refresh;
  // 3. Create new guest connection for refresh operation
  const refreshConnection: api.IConnection = { host: connection.host };
  // 4. Call refresh endpoint with refresh token
  const refreshResult = await authorize_guest_refresh(refreshConnection, {
    body: {
      refresh_token: refreshToken,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallGuest.IRefresh,
  });
  typia.assert(refreshResult);
  // 5. Validate response structure
  TestValidator.equals("guest id preserved", refreshResult.id, joinResult.id);
  TestValidator.equals(
    "device fingerprint preserved",
    refreshResult.device_fingerprint,
    joinResult.device_fingerprint,
  );
  // 6. Validate new tokens are issued
  TestValidator.notEquals(
    "new access token issued",
    refreshResult.token.access,
    joinResult.token.access,
  );
  TestValidator.notEquals(
    "new refresh token issued",
    refreshResult.token.refresh,
    joinResult.token.refresh,
  );
  // 7. Validate expiration timestamps are updated
  TestValidator.notEquals(
    "access token expiration updated",
    refreshResult.token.expired_at,
    joinResult.token.expired_at,
  );
  TestValidator.predicate("refreshable_until is valid date-time", () => {
    const date = new Date(refreshResult.token.refreshable_until);
    return !isNaN(date.getTime());
  });
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IShoppingMallGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallGuest";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

export async function test_api_guest_refresh_expired_token(
  connection: api.IConnection,
): Promise<void> {
  /**
   * Test guest refresh token expiration handling.
   * 1. Create a valid guest session to obtain tokens
   * 2. Attempt to refresh with an invalid/expired refresh token
   * 3. Verify 401 Unauthorized error is returned
   * 4. Confirm the error indicates token expiration/invalidity
   */
  // 1. Create guest connection and establish valid session
  const guestConnection: api.IConnection = { host: connection.host };
  const validSession = await authorize_guest_join(guestConnection, {
    body: {
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(validSession);
  // Verify we got valid tokens
  TestValidator.predicate(
    "has access token",
    validSession.token.access.length > 0,
  );
  TestValidator.predicate(
    "has refresh token",
    validSession.token.refresh.length > 0,
  );
  // 2. Create a new connection for the refresh attempt
  const refreshConnection: api.IConnection = { host: connection.host };
  // 3. Attempt to refresh with an invalid/expired refresh token
  // Use a deliberately invalid token to simulate expiration
  const invalidRefreshBody = {
    refresh_token: "invalid_expired_token_12345",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallGuest.IRefresh;
  // 4. Verify that refreshing with invalid token throws 401 error
  await TestValidator.httpError(
    "refresh with expired token returns 401",
    401,
    async () => {
      await authorize_guest_refresh(refreshConnection, {
        body: invalidRefreshBody,
      });
    },
  );
  // 5. Verify that the original valid session still works (token hasn't been invalidated)
  const validRefreshBody = {
    refresh_token: validSession.token.refresh,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallGuest.IRefresh;
  const refreshedSession = await authorize_guest_refresh(guestConnection, {
    body: validRefreshBody,
  });
  typia.assert(refreshedSession);
  // 6. Verify the valid refresh succeeded and got new tokens
  TestValidator.predicate(
    "refreshed session has new access token",
    refreshedSession.token.access.length > 0,
  );
  TestValidator.predicate(
    "refreshed session has new refresh token",
    refreshedSession.token.refresh.length > 0,
  );
  TestValidator.notEquals(
    "access token rotated",
    validSession.token.access,
    refreshedSession.token.access,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IShoppingMallGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallGuest";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

export async function test_api_guest_refresh_token_rotation(
  connection: api.IConnection,
): Promise<void> {
  /**
   * Test the refresh token rotation security feature for guest sessions.
   * Validates that refresh tokens are single-use and rotated on each successful refresh,
   * preventing replay attacks by rejecting attempts to reuse consumed tokens.
   */
  // Step 1: Create initial guest session to obtain first refresh token
  const guestConnection1: api.IConnection = { host: connection.host };
  const initialAuth = await authorize_guest_join(guestConnection1, {
    body: {
      href: "https://example.com/products",
      referrer: "https://google.com/search",
      ip: "192.168.1.100",
    } satisfies IShoppingMallGuest.IJoin,
  });
  typia.assert(initialAuth);
  const firstRefreshToken = initialAuth.token.refresh;
  // Step 2: Refresh the session using the first refresh token
  const guestConnection2: api.IConnection = { host: connection.host };
  const refreshedAuth = await authorize_guest_refresh(guestConnection2, {
    body: {
      refresh_token: firstRefreshToken,
      href: "https://example.com/cart",
      referrer: "https://example.com/products",
      ip: "192.168.1.100",
    } satisfies IShoppingMallGuest.IRefresh,
  });
  typia.assert(refreshedAuth);
  const secondRefreshToken = refreshedAuth.token.refresh;
  // Verify that the refresh token was rotated (new token is different from old)
  TestValidator.notEquals(
    "refresh token rotated",
    firstRefreshToken,
    secondRefreshToken,
  );
  // Step 3: Attempt to reuse the first (consumed) refresh token
  // This should fail with 401 Unauthorized because the token was rotated
  const guestConnection3: api.IConnection = { host: connection.host };
  await TestValidator.httpError(
    "reused refresh token rejected with 401",
    401,
    async () => {
      await authorize_guest_refresh(guestConnection3, {
        body: {
          refresh_token: firstRefreshToken,
          href: "https://example.com/checkout",
          referrer: "https://example.com/cart",
          ip: "192.168.1.100",
        } satisfies IShoppingMallGuest.IRefresh,
      });
    },
  );
  // Step 4: Verify that the new refresh token still works
  const guestConnection4: api.IConnection = { host: connection.host };
  const reRefreshedAuth = await authorize_guest_refresh(guestConnection4, {
    body: {
      refresh_token: secondRefreshToken,
      href: "https://example.com/checkout",
      referrer: "https://example.com/cart",
      ip: "192.168.1.100",
    } satisfies IShoppingMallGuest.IRefresh,
  });
  typia.assert(reRefreshedAuth);
  // Verify the token was rotated again
  TestValidator.notEquals(
    "refresh token rotated again",
    secondRefreshToken,
    reRefreshedAuth.token.refresh,
  );
}

