 * This test validates the filtering capabilities of the seller approval request listing endpoint,
 * including status filtering, date range filtering, and shop name partial matching.
 */
export async function test_api_seller_approval_request_filter_by_status_and_date(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register and authenticate as administrator
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: "admin@test.com",
      password: "1234",
    },
  });
  // 2. Register multiple sellers to create approval requests
  const seller1Email = typia.random<string & tags.Format<"email">>();
  const seller1Connection: api.IConnection = { host: connection.host };
  await authorize_seller_join(seller1Connection, {
    body: {
      email: seller1Email,
      password: "1234",
      shop_name: "TestShop Alpha",
      shop_description: "First test shop",
    },
  });
  const seller1SubmitTime = new Date();
  // Small delay to ensure different timestamps
  await new Promise((resolve) => setTimeout(resolve, 100));
  const seller2Email = typia.random<string & tags.Format<"email">>();
  const seller2Connection: api.IConnection = { host: connection.host };
  await authorize_seller_join(seller2Connection, {
    body: {
      email: seller2Email,
      password: "1234",
      shop_name: "TestShop Beta",
      shop_description: "Second test shop",
    },
  });
  const seller2SubmitTime = new Date();
  await new Promise((resolve) => setTimeout(resolve, 100));
  const seller3Email = typia.random<string & tags.Format<"email">>();
  const seller3Connection: api.IConnection = { host: connection.host };
  await authorize_seller_join(seller3Connection, {
    body: {
      email: seller3Email,
      password: "1234",
      shop_name: "Alpha Shop Gamma",
      shop_description: "Third test shop",
    },
  });
  const seller3SubmitTime = new Date();
  // Get all pending requests to find request IDs
  const allPendingRequests =
    await api.functional.shoppingMall.seller.seller_approval_requests.index(
      adminConnection,
      {
        body: {
          status: "pending",
        } satisfies IShoppingMallSellerApprovalRequest.IRequest,
      },
    );
  typia.assert(allPendingRequests);
  // Find request IDs for each seller
  const seller1RequestId = allPendingRequests.data.find(
    (req) => req.seller.email === seller1Email,
  )?.id;
  const seller2RequestId = allPendingRequests.data.find(
    (req) => req.seller.email === seller2Email,
  )?.id;
  const seller3RequestId = allPendingRequests.data.find(
    (req) => req.seller.email === seller3Email,
  )?.id;
  // Validate we found all three requests
  TestValidator.predicate(
    "found seller 1 request",
    seller1RequestId !== undefined,
  );
  TestValidator.predicate(
    "found seller 2 request",
    seller2RequestId !== undefined,
  );
  TestValidator.predicate(
    "found seller 3 request",
    seller3RequestId !== undefined,
  );
  // 3. Approve first seller request
  if (seller1RequestId) {
    const approvedRequest =
      await api.functional.shoppingMall.admin.seller_approval_requests.update(
        adminConnection,
        {
          requestId: seller1RequestId,
          body: {
            status: "approved",
          } satisfies IShoppingMallSellerApprovalRequest.IUpdate,
        },
      );
    typia.assert(approvedRequest);
  }
  // Reject second seller request
  if (seller2RequestId) {
    const rejectedRequest =
      await api.functional.shoppingMall.admin.seller_approval_requests.update(
        adminConnection,
        {
          requestId: seller2RequestId,
          body: {
            status: "rejected",
            rejection_reason: "Test rejection",
          } satisfies IShoppingMallSellerApprovalRequest.IUpdate,
        },
      );
    typia.assert(rejectedRequest);
  }
  // 4. Test filtering by status='pending' and submittedAfter
  const pendingAfterFilter =
    await api.functional.shoppingMall.seller.seller_approval_requests.index(
      adminConnection,
      {
        body: {
          status: "pending",
          submittedAfter: seller2SubmitTime.toISOString(),
        } satisfies IShoppingMallSellerApprovalRequest.IRequest,
      },
    );
  typia.assert(pendingAfterFilter);
  // Verify only seller3 (pending and after seller2 time) is returned
  TestValidator.equals(
    "pending after filter returns correct count",
    pendingAfterFilter.data.length,
    1,
  );
  TestValidator.predicate(
    "pending after filter returns seller3",
    pendingAfterFilter.data[0]?.seller.email === seller3Email,
  );
  TestValidator.predicate(
    "pending after filter has correct status",
    pendingAfterFilter.data[0]?.status === "pending",
  );
  // 5. Test filtering by status='approved' and submittedBefore
  const approvedBeforeFilter =
    await api.functional.shoppingMall.seller.seller_approval_requests.index(
      adminConnection,
      {
        body: {
          status: "approved",
          submittedBefore: seller3SubmitTime.toISOString(),
        } satisfies IShoppingMallSellerApprovalRequest.IRequest,
      },
    );
  typia.assert(approvedBeforeFilter);
  // Verify only seller1 (approved and before seller3 time) is returned
  TestValidator.equals(
    "approved before filter returns correct count",
    approvedBeforeFilter.data.length,
    1,
  );
  TestValidator.predicate(
    "approved before filter returns seller1",
    approvedBeforeFilter.data[0]?.seller.email === seller1Email,
  );
  TestValidator.predicate(
    "approved before filter has correct status",
    approvedBeforeFilter.data[0]?.status === "approved",
  );
  // 6. Test filtering by shopName partial match
  const shopNameFilter =
    await api.functional.shoppingMall.seller.seller_approval_requests.index(
      adminConnection,
      {
        body: {
          shopName: "Alpha",
        } satisfies IShoppingMallSellerApprovalRequest.IRequest,
      },
    );
  typia.assert(shopNameFilter);
  // Verify both "TestShop Alpha" and "Alpha Shop Gamma" are returned
  TestValidator.predicate(
    "shop name filter returns at least 2 results",
    shopNameFilter.data.length >= 2,
  );
  const alphaShopNames = shopNameFilter.data.map((req) => req.seller.shop_name);
  TestValidator.predicate(
    "shop name filter includes TestShop Alpha",
    alphaShopNames.some((name) => name.includes("Alpha")),
  );
  // 7. Test filtering with no matches (should return empty array)
  const noMatchFilter =
    await api.functional.shoppingMall.seller.seller_approval_requests.index(
      adminConnection,
      {
        body: {
          status: "pending",
          shopName: "NonExistentShop",
        } satisfies IShoppingMallSellerApprovalRequest.IRequest,
      },
    );
  typia.assert(noMatchFilter);
  TestValidator.equals(
    "no match filter returns empty array",
    noMatchFilter.data.length,
    0,
  );
  TestValidator.equals(
    "no match filter has correct pagination records",
    noMatchFilter.pagination.records,
    0,
  );
  // 8. Test pagination with filtered results
  const paginatedFilter =
    await api.functional.shoppingMall.seller.seller_approval_requests.index(
      adminConnection,
      {
        body: {
          status: "pending",
          page: 1,
          limit: 1,
        } satisfies IShoppingMallSellerApprovalRequest.IRequest,
      },
    );
  typia.assert(paginatedFilter);
  TestValidator.equals(
    "pagination limit respected",
    paginatedFilter.data.length,
    1,
  );
  TestValidator.equals(
    "pagination limit in response",
    paginatedFilter.pagination.limit,
    1,
  );
  TestValidator.equals(
    "pagination current page",
    paginatedFilter.pagination.current,
    1,
  );
}

