  // 9. Validate: Request details
  if (foundRequest) {
    TestValidator.equals(
      "request status is pending",
      foundRequest.status,
      "pending",
    );
    TestValidator.equals(
      "request reason matches",
      foundRequest.reason,
      approvalRequest.reason,
    );
    TestValidator.predicate(
      "submitted_at is valid datetime",
      foundRequest.submitted_at !== null,
    );
    TestValidator.equals(
      "responded_at is null for pending",
      foundRequest.responded_at,
      null,
    );
    // 10. Validate: Seller information
    TestValidator.equals(
      "seller id matches",
      foundRequest.seller.id,
      approvalRequest.seller.id,
    );
    TestValidator.equals(
      "seller approval_status is pending",
      foundRequest.seller.approval_status,
      "pending",
    );
  }
  // 11. Validate: Ordering by submitted_at DESC
  if (result.data.length > 1) {
    TestValidator.predicate(
      "requests ordered by submitted_at DESC",
      result.data.every(
        (req, index, array) =>
          index === 0 ||
          new Date(req.submitted_at) <= new Date(array[index - 1].submitted_at),
      ),
    );
  }
}

