    approvalRequest.seller.email,
    seller.email,
  );
  TestValidator.equals(
    "seller shop_name matches",
    approvalRequest.seller.shop_name,
    seller.shop_name,
  );
  TestValidator.equals(
    "seller approval_status is pending",
    approvalRequest.seller.approval_status,
    "pending",
