/**
 * Test seller approval request resubmission after rejection.
 *
 * This test validates the complete resubmission workflow where a seller whose
 * previous approval request was rejected can submit a new request with an
 * updated reason. The test covers:
 * 1. Seller registration and initial approval request submission
 * 2. Administrator rejection of the request with a reason
 * 3. Seller resubmission with an improved reason
 * 4. Verification that the new request is created with pending status
 */
export async function test_api_seller_approval_request_resubmission_after_rejection(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create seller account and get credentials
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      shop_name: RandomGenerator.name(2),
      shop_description: RandomGenerator.paragraph({ sentences: 2 }),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerAuth);
  // 2. Submit initial approval request as seller
  const initialRequest =
    await generate_random_shopping_mall_seller_seller_approval_requests_create(
      sellerConnection,
      {
        body: {
          reason: RandomGenerator.paragraph({ sentences: 3 }),
        },
      },
    );
  typia.assert(initialRequest);
  TestValidator.equals(
    "initial request status",
    initialRequest.status,
    "pending",
  );
  // 3. Authenticate as administrator
  const adminConnection: api.IConnection = { host: connection.host };
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  await authorize_admin_join(adminConnection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // 4. Reject the seller's approval request
  const rejectionReason =
    "Please provide more detailed business information and product catalog.";
  const rejectedRequest =
    await api.functional.shoppingMall.admin.seller_approval_requests.update(
      adminConnection,
      {
        requestId: initialRequest.id,
        body: {
          status: "rejected",
          rejection_reason: rejectionReason,
        } satisfies IShoppingMallSellerApprovalRequest.IUpdate,
      },
    );
  typia.assert(rejectedRequest);
  TestValidator.equals("request rejected", rejectedRequest.status, "rejected");
  // 5. Resubmit approval request with improved reason
  const improvedReason =
    "We are a established retailer with 5 years of experience, offering premium handcrafted goods. Our product catalog includes over 200 items across home decor, accessories, and artisanal food products. We have positive customer reviews and established supply chains.";
  const resubmittedRequest =
    await generate_random_shopping_mall_seller_seller_approval_requests_create(
      sellerConnection,
      {
        body: {
          reason: improvedReason,
        },
      },
    );
  typia.assert(resubmittedRequest);
  // 6. Validate resubmission results
  TestValidator.notEquals(
    "IDs differ",
    resubmittedRequest.id,
    initialRequest.id,
  );
  TestValidator.equals(
    "new request status is pending",
    resubmittedRequest.status,
    "pending",
  );
  TestValidator.equals(
    "improved reason submitted",
    resubmittedRequest.reason,
    improvedReason,
