    "first request status remains pending after failed second attempt",
    firstRequest.status,
    "pending",
  );
  TestValidator.predicate(
    "first request reason unchanged",
    firstRequest.reason.length > 0,
  );
  TestValidator.predicate(
    "first request has valid ID",
    firstRequest.id.length > 0,
  );
}

