import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

export async function test_api_category_filtering_by_parent(
  connection: api.IConnection,
): Promise<void> {
  /**
   * Test category filtering functionality by parent category relationship.
   *
   * This test validates that the shopping mall category API correctly filters
   * categories based on parent category relationships. It tests retrieving
   * top-level categories, subcategories of a specific parent, and handling
   * non-existent parent IDs.
   */
  // 1. Create actor-specific connection from base connection
  const customerConnection: api.IConnection = { host: connection.host };
  // 2. Retrieve all top-level categories by filtering with parentId=null
  const topLevelCategories = await api.functional.shoppingMall.categories.index(
    customerConnection,
    {
      body: {
        parentId: null,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(topLevelCategories);
  // 3. Validate response contains top-level categories with parent=null
  TestValidator.predicate(
    "top-level categories exist",
    topLevelCategories.data.length > 0,
  );
  // Verify all top-level categories have parent=null
  for (const category of topLevelCategories.data) {
    TestValidator.equals(
      `category ${category.id} has no parent`,
      category.parent,
      null,
    );
  }
  // 4. Select one top-level category ID from the results
  const selectedParentId = topLevelCategories.data[0].id;
  // 5. Call PATCH /shoppingMall/categories with parentId set to the selected category ID
  const subcategories = await api.functional.shoppingMall.categories.index(
    customerConnection,
    {
      body: {
        parentId: selectedParentId,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(subcategories);
  // 6. Verify response contains only subcategories of the selected parent
  // Note: There may be 0 or more subcategories, both are valid
  // 7. Confirm all returned categories have the correct parent field
  for (const subcategory of subcategories.data) {
    TestValidator.equals(
      `subcategory ${subcategory.id} has correct parent`,
      subcategory.parent?.id,
      selectedParentId,
    );
  }
  // 8. Test with a non-existent parent ID (generate random UUID)
  const nonExistentParentId = typia.random<string & tags.Format<"uuid">>();
  const emptyResults = await api.functional.shoppingMall.categories.index(
    customerConnection,
    {
      body: {
        parentId: nonExistentParentId,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(emptyResults);
  // 9. Verify empty results are returned for non-existent parent
  TestValidator.equals(
    "non-existent parent returns empty results",
    emptyResults.data.length,
    0,
  );
  // 10. Validate pagination metadata reflects filtered results count
  TestValidator.equals(
    "top-level pagination records match data length",
    topLevelCategories.pagination.records,
    topLevelCategories.data.length,
  );
  TestValidator.equals(
    "subcategories pagination records match data length",
    subcategories.pagination.records,
    subcategories.data.length,
  );
  TestValidator.equals(
    "empty results pagination records is zero",
    emptyResults.pagination.records,
    0,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCategory";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

/**
 * Test category search functionality with pagination and sorting options.
 *
 * This test validates the category search API by testing various search parameters,
 * pagination controls, and sorting options. It ensures that categories can be
 * effectively filtered and browsed by customers.
 */
export async function test_api_category_search_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Test basic search with name parameter
  const searchConnection: api.IConnection = { host: connection.host };
  const searchBody = {
    name: "Electronics",
    page: 1,
    limit: 20,
  } satisfies IShoppingMallCategory.IRequest;
  const searchResult = await api.functional.shoppingMall.categories.index(
    searchConnection,
    { body: searchBody },
  );
  typia.assert(searchResult);
  // Verify search results contain matching categories
  TestValidator.predicate(
    "search returns valid pagination",
    searchResult.pagination.current >= 1,
  );
  TestValidator.predicate(
    "search returns valid limit",
    searchResult.pagination.limit > 0,
  );
  // 2. Test pagination with page=2 and limit=10
  const paginationBody = {
    page: 2,
    limit: 10,
  } satisfies IShoppingMallCategory.IRequest;
  const paginationResult = await api.functional.shoppingMall.categories.index(
    searchConnection,
    { body: paginationBody },
  );
  typia.assert(paginationResult);
  // Verify pagination metadata
  TestValidator.equals(
    "pagination current page",
    paginationResult.pagination.current,
    2,
  );
  TestValidator.equals(
    "pagination limit",
    paginationResult.pagination.limit,
    10,
  );
  TestValidator.predicate(
    "pagination has valid total records",
    paginationResult.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination has valid total pages",
    paginationResult.pagination.pages >= 0,
  );
  // 3. Test sorting by name in descending order
  const sortByNameBody = {
    sortBy: "name",
    sortOrder: "desc",
    page: 1,
    limit: 20,
  } satisfies IShoppingMallCategory.IRequest;
  const sortByNameResult = await api.functional.shoppingMall.categories.index(
    searchConnection,
    { body: sortByNameBody },
  );
  typia.assert(sortByNameResult);
  // Verify sorting by name descending
  if (sortByNameResult.data.length > 1) {
    TestValidator.predicate(
      "categories sorted by name descending",
      sortByNameResult.data.every((category, index, array) => {
        if (index === 0) return true;
        return category.name.localeCompare(array[index - 1].name) <= 0;
      }),
    );
  }
  // 4. Test sorting by createdAt in ascending order
  const sortByDateBody = {
    sortBy: "createdAt",
    sortOrder: "asc",
    page: 1,
    limit: 20,
  } satisfies IShoppingMallCategory.IRequest;
  const sortByDateResult = await api.functional.shoppingMall.categories.index(
    searchConnection,
    { body: sortByDateBody },
  );
  typia.assert(sortByDateResult);
  // Verify sorting by createdAt ascending
  if (sortByDateResult.data.length > 1) {
    TestValidator.predicate(
      "categories sorted by createdAt ascending",
      sortByDateResult.data.every((category, index, array) => {
        if (index === 0) return true;
        return (
          new Date(category.created_at).getTime() >=
          new Date(array[index - 1].created_at).getTime()
        );
      }),
    );
  }
  // 5. Test with includeSubcategories flag
  const includeSubcategoriesBody = {
    includeSubcategories: true,
    page: 1,
    limit: 20,
  } satisfies IShoppingMallCategory.IRequest;
  const includeSubcategoriesResult =
    await api.functional.shoppingMall.categories.index(searchConnection, {
      body: includeSubcategoriesBody,
    });
  typia.assert(includeSubcategoriesResult);
  TestValidator.predicate(
    "includeSubcategories returns valid response",
    includeSubcategoriesResult.pagination.current >= 1,
  );
  // 6. Test with parentId filter (top-level categories)
  const topLevelBody = {
    parentId: null,
    page: 1,
    limit: 20,
  } satisfies IShoppingMallCategory.IRequest;
  const topLevelResult = await api.functional.shoppingMall.categories.index(
    searchConnection,
    { body: topLevelBody },
  );
  typia.assert(topLevelResult);
  // Verify all returned categories are top-level (parent is null)
  TestValidator.predicate(
    "top-level categories have null parent",
    topLevelResult.data.every((category) => category.parent === null),
  );
  // 7. Test empty search (no filters)
  const emptySearchBody = {} satisfies IShoppingMallCategory.IRequest;
  const emptySearchResult = await api.functional.shoppingMall.categories.index(
    searchConnection,
    { body: emptySearchBody },
  );
  typia.assert(emptySearchResult);
  TestValidator.predicate(
    "empty search returns valid pagination",
    emptySearchResult.pagination.current >= 1,
  );
}

