      await api.functional.shoppingMall.customer.customers.me.cart_items.create(
        customerConnection,
        {
          body: {
            variantId: variantIdOutOfStock,
            quantity: 1,
          } satisfies IShoppingMallCartItem.ICreate,
        },
      );
