    "all snapshots are JSON strings",
    typeof retrievedOrderItem.productSnapshot === "string" &&
      typeof retrievedOrderItem.variantSnapshot === "string" &&
      typeof retrievedOrderItem.sellerProfileSnapshot === "string",
