export async function test_api_shipment_item_multi_seller_separation(
  connection: api.IConnection,
): Promise<void> {
  // 1. Setup: Create admin account
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: "admin@test.com",
      password: "1234",
      href: "https://test.com/admin",
      referrer: "https://test.com",
    } satisfies IShoppingMallAdmin.IJoin,
  });
  // 2. Setup: Create Seller A account
  const sellerAConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerAConnection, {
    body: {
      email: "sellerA@test.com",
      password: "1234",
      shop_name: "Seller A Shop",
      shop_description: "Seller A's shop description",
      href: "https://test.com/seller",
      referrer: "https://test.com",
    } satisfies IShoppingMallSeller.IJoin,
  });
  // 3. Setup: Create Seller B account
  const sellerBConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerBConnection, {
    body: {
      email: "sellerB@test.com",
      password: "1234",
      shop_name: "Seller B Shop",
      shop_description: "Seller B's shop description",
      href: "https://test.com/seller",
      referrer: "https://test.com",
    } satisfies IShoppingMallSeller.IJoin,
  });
  // 4. Setup: Create customer account
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: {
      email: "customer@test.com",
      password: "1234",
      display_name: "Test Customer",
      phone_number: "01012345678",
      href: "https://test.com/customer",
      referrer: "https://test.com",
    } satisfies IShoppingMallCustomer.IJoin,
  });
  // 5. Customer creates order with items (may be from multiple sellers)
  const order =
    await generate_random_shopping_mall_customer_customers_me_orders_create(
      customerConnection,
      {},
    );
  typia.assert(order);
  // 6. Group order items by seller
  const sellerMap = new Map<string, IShoppingMallOrderItem[]>();
  for (const item of order.orderItems) {
    const items = sellerMap.get(item.sellerId) || [];
    items.push(item);
    sellerMap.set(item.sellerId, items);
  }
  // 7. Get unique seller IDs
  const sellerIds = Array.from(sellerMap.keys());
  // 8. Create shipments for each seller
  const shipments: IShoppingMallShipment[] = [];
  const carrierNames = ["FedEx", "UPS", "DHL", "EMS"] as const;
  for (let i = 0; i < sellerIds.length; i++) {
    const sellerId = sellerIds[i];
    const sellerItems = sellerMap.get(sellerId)!;
    const carrier = carrierNames[i % carrierNames.length];
    // Create shipment for this seller's items
    const shipment =
      await generate_random_shopping_mall_seller_sellers_me_shipments_create(
        i === 0 ? sellerAConnection : sellerBConnection,
        {
          body: {
            order_item_ids: sellerItems.map((item) => item.id),
            tracking_carrier: carrier,
            tracking_number: carrier + RandomGenerator.alphaNumeric(12),
          } satisfies IShoppingMallShipment.ICreate,
        },
      );
    typia.assert(shipment);
    shipments.push(shipment);
  }
  // 9. Validate each shipment contains only items from one seller
  for (const shipment of shipments) {
    const firstItemSellerId = shipment.orderItems[0].sellerId;
    // All items in this shipment must have the same seller_id
    for (const item of shipment.orderItems) {
      TestValidator.equals(
        `Shipment ${shipment.id} contains only ${firstItemSellerId}'s items`,
        item.sellerId,
        firstItemSellerId,
      );
    }
  }
  // 10. If we have multiple sellers, validate separation
  if (sellerIds.length >= 2) {
    const sellerAShipment = shipments[0];
    const sellerBShipment = shipments[1];
    // Validate different sellers
    TestValidator.notEquals(
      "Different sellers in multi-seller order",
      sellerAShipment.orderItems[0].sellerId,
      sellerBShipment.orderItems[0].sellerId,
    );
    // Admin retrieves order items from each shipment
    const sellerAOrderItem =
      await api.functional.shoppingMall.admin.shipments.items.at(
        adminConnection,
        {
          shipmentId: sellerAShipment.id,
          itemId: sellerAShipment.orderItems[0].id,
        },
      );
    typia.assert(sellerAOrderItem);
    const sellerBOrderItem =
      await api.functional.shoppingMall.admin.shipments.items.at(
        adminConnection,
        {
          shipmentId: sellerBShipment.id,
          itemId: sellerBShipment.orderItems[0].id,
        },
      );
    typia.assert(sellerBOrderItem);
    // Validate seller_id matches in admin response
    TestValidator.equals(
      "Admin view: Seller A item seller_id matches",
      sellerAOrderItem.sellerId,
      sellerAShipment.orderItems[0].sellerId,
    );
    TestValidator.equals(
      "Admin view: Seller B item seller_id matches",
      sellerBOrderItem.sellerId,
      sellerBShipment.orderItems[0].sellerId,
    );
  }
  // 11. Validate tracking information is correctly associated
  for (const shipment of shipments) {
    TestValidator.predicate(
      `Shipment ${shipment.id} has tracking carrier`,
      shipment.tracking_carrier.length > 0,
    );
    TestValidator.predicate(
      `Shipment ${shipment.id} has tracking number`,
      shipment.tracking_number.length > 0,
    );
  }
  // 12. Validate snapshots are preserved for all order items
  for (const shipment of shipments) {
    for (const item of shipment.orderItems) {
      TestValidator.predicate(
        `Item ${item.id} has product snapshot`,
        item.productSnapshot.length > 0,
      );
      TestValidator.predicate(
        `Item ${item.id} has variant snapshot`,
        item.variantSnapshot.length > 0,
      );
      TestValidator.predicate(
        `Item ${item.id} has seller profile snapshot`,
        item.sellerProfileSnapshot.length > 0,
      );
    }
  }
  // 13. Validate order items status updated to shipped
  for (const shipment of shipments) {
    for (const item of shipment.orderItems) {
      TestValidator.equals(
        `Item ${item.id} status is shipped after shipment creation`,
        item.status,
        "shipped",
      );
    }
  }
}

import api from "@ORGANIZATION/PROJECT-api";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallReview";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReview";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

/**
 * Test the primary success path for browsing product reviews with pagination.
 *
 * This test validates:
 * 1. Default pagination behavior (page=1, limit=20)
 * 2. Response structure with pagination metadata and review summaries
 * 3. Review sorting by creation date (newest first)
 * 4. Pagination navigation to subsequent pages
 * 5. Exclusion of soft-deleted reviews
 * 6. Edge cases (empty results, last page)
 */
export async function test_api_review_listing_with_pagination(
  connection: api.IConnection,
): Promise<void> {
  // Create a dedicated connection for the review listing endpoint
  const reviewConnection: api.IConnection = { host: connection.host };
  // Test 1: Retrieve first page with default parameters
  const firstPage = await api.functional.shoppingMall.reviews.index(
    reviewConnection,
    {
      body: {} satisfies IShoppingMallReview.IRequest,
    },
  );
  typia.assert(firstPage);
  // Validate pagination metadata
  TestValidator.predicate(
    "first page current should be 1",
    firstPage.pagination.current === 1,
  );
  TestValidator.predicate(
    "first page limit should be default 20",
    firstPage.pagination.limit === 20,
  );
  TestValidator.predicate(
    "total records should be non-negative",
    firstPage.pagination.records >= 0,
  );
  TestValidator.predicate(
    "total pages should be non-negative",
    firstPage.pagination.pages >= 0,
  );
  // Validate review summaries structure
  for (const review of firstPage.data) {
    // Verify required fields exist
    TestValidator.predicate(
      `review ${review.id} has valid UUID`,
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
        review.id,
      ),
    );
    TestValidator.predicate(
      `review ${review.id} has valid rating (1-5)`,
      review.rating >= 1 && review.rating <= 5,
    );
    // Verify customer info
    TestValidator.predicate(
      `review ${review.id} has customer with valid UUID`,
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
        review.customer.id,
      ),
    );
    TestValidator.predicate(
      `review ${review.id} has customer with valid email`,
      /^[a-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\.[a-z0-9!#$%&'*+/=?^_`{|}~-]+)*@(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(
        review.customer.email,
      ),
    );
    // Verify order item info
    TestValidator.predicate(
      `review ${review.id} has order item with valid UUID`,
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
        review.orderItem.id,
      ),
    );
    // Verify timestamps exist
    TestValidator.predicate(
      `review ${review.id} has created_at`,
      review.created_at !== undefined,
    );
    TestValidator.predicate(
      `review ${review.id} has updated_at`,
      review.updated_at !== undefined,
    );
    // Verify soft-deleted reviews are excluded (deleted_at should be null)
    TestValidator.equals(
      `review ${review.id} should not be deleted`,
      review.deleted_at,
      null,
    );
  }
  // Test 2: Verify sorting by created_at (newest first)
  if (firstPage.data.length > 1) {
    for (let i = 1; i < firstPage.data.length; i++) {
      TestValidator.predicate(
        `review ${i} should be older or same as review ${i - 1}`,
        new Date(firstPage.data[i].created_at).getTime() <=
          new Date(firstPage.data[i - 1].created_at).getTime(),
      );
    }
  }
  // Test 3: Pagination - request page 2 with limit 10
  if (firstPage.pagination.pages >= 2) {
    const secondPage = await api.functional.shoppingMall.reviews.index(
      reviewConnection,
      {
        body: {
          page: 2,
          limit: 10,
        } satisfies IShoppingMallReview.IRequest,
      },
    );
    typia.assert(secondPage);
    // Validate pagination metadata
    TestValidator.equals(
      "second page current should be 2",
      secondPage.pagination.current,
      2,
    );
    TestValidator.equals(
      "second page limit should be 10",
      secondPage.pagination.limit,
      10,
    );
    // Verify no duplicate reviews between pages
    const firstPageIds = new Set(firstPage.data.map((r) => r.id));
    const hasDuplicates = secondPage.data.some((r) => firstPageIds.has(r.id));
    TestValidator.predicate(
      "second page should not contain reviews from first page",
      !hasDuplicates,
    );
  }
  // Test 4: Test with custom limit (edge case: limit = 1)
  const singleItemPage = await api.functional.shoppingMall.reviews.index(
    reviewConnection,
    {
      body: {
        page: 1,
        limit: 1,
      } satisfies IShoppingMallReview.IRequest,
    },
  );
  typia.assert(singleItemPage);
  TestValidator.equals(
    "single item page should have at most 1 review",
    singleItemPage.data.length,
    singleItemPage.pagination.records > 0 ? 1 : 0,
  );
  TestValidator.equals(
    "single item page limit should be 1",
    singleItemPage.pagination.limit,
    1,
  );
  // Test 5: Test with rating filter
  const fiveStarReviews = await api.functional.shoppingMall.reviews.index(
    reviewConnection,
    {
      body: {
        page: 1,
        limit: 10,
        rating: 5,
      } satisfies IShoppingMallReview.IRequest,
    },
  );
  typia.assert(fiveStarReviews);
  // Verify all returned reviews have rating 5
  for (const review of fiveStarReviews.data) {
    TestValidator.equals(
      `filtered review ${review.id} should have rating 5`,
      review.rating,
      5,
    );
  }
  // Test 6: Test empty result set (using a filter that likely returns no results)
  const emptyPage = await api.functional.shoppingMall.reviews.index(
    reviewConnection,
    {
      body: {
        page: 9999,
        limit: 10,
      } satisfies IShoppingMallReview.IRequest,
    },
  );
  typia.assert(emptyPage);
  TestValidator.equals(
    "empty page should have 0 reviews",
    emptyPage.data.length,
    0,
  );
  TestValidator.equals(
    "empty page current should be 9999",
    emptyPage.pagination.current,
    9999,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallReview";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReview";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

/**
 * Test review filtering capabilities by product ID and rating value.
 *
 * This test validates the comprehensive filtering functionality of the review
 * listing endpoint, including product-specific queries, rating-based filtering,
 * date range constraints, text search, and pagination with filtered results.
 */
export async function test_api_review_filtering_by_product_and_rating(
  connection: api.IConnection,
): Promise<void> {
  // Setup: Create customer connection for authenticated requests
  const customerConnection: api.IConnection = { host: connection.host };
  // 1. Test productId filter with a valid UUID
  const productId = typia.random<string & tags.Format<"uuid">>();
  const productFilteredReviews =
    await api.functional.shoppingMall.reviews.index(customerConnection, {
      body: {
        productId: productId,
        page: 1,
        limit: 20,
      } satisfies IShoppingMallReview.IRequest,
    });
  typia.assert(productFilteredReviews);
  TestValidator.predicate(
    "product filter returns valid response structure",
    Array.isArray(productFilteredReviews.data),
  );
  // 2. Test rating filter with value 5
  const rating5FilteredReviews =
    await api.functional.shoppingMall.reviews.index(customerConnection, {
      body: {
        rating: 5,
        page: 1,
        limit: 20,
      } satisfies IShoppingMallReview.IRequest,
    });
  typia.assert(rating5FilteredReviews);
  TestValidator.equals(
    "rating filter returns valid pagination",
    rating5FilteredReviews.pagination.current,
    1,
  );
  TestValidator.predicate(
    "rating filter response has correct structure",
    rating5FilteredReviews.data.every((r) => r.rating === 5),
  );
  // 3. Test combined filters: productId + rating
  const combinedFilteredReviews =
    await api.functional.shoppingMall.reviews.index(customerConnection, {
      body: {
        productId: productId,
        rating: 4,
        page: 1,
        limit: 20,
      } satisfies IShoppingMallReview.IRequest,
    });
  typia.assert(combinedFilteredReviews);
  TestValidator.predicate(
    "combined filter returns valid response",
    combinedFilteredReviews.pagination.records >= 0,
  );
  // 4. Test date range filtering
  const startDate = new Date();
  startDate.setHours(startDate.getHours() - 24);
  const endDate = new Date();
  const dateFilteredReviews = await api.functional.shoppingMall.reviews.index(
    customerConnection,
    {
      body: {
        productId: productId,
        startDate: startDate.toISOString(),
        endDate: endDate.toISOString(),
        page: 1,
        limit: 20,
      } satisfies IShoppingMallReview.IRequest,
    },
  );
  typia.assert(dateFilteredReviews);
  TestValidator.predicate(
    "date range filter returns valid response",
    dateFilteredReviews.pagination.current === 1,
  );
  // 5. Test text search filter with keyword
  const searchFilteredReviews = await api.functional.shoppingMall.reviews.index(
    customerConnection,
    {
      body: {
        search: "excellent",
        page: 1,
        limit: 20,
      } satisfies IShoppingMallReview.IRequest,
    },
  );
  typia.assert(searchFilteredReviews);
  TestValidator.predicate(
    "text search returns valid response structure",
    Array.isArray(searchFilteredReviews.data),
  );
  // 6. Test pagination with filtered results
  const paginatedReviews = await api.functional.shoppingMall.reviews.index(
    customerConnection,
    {
      body: {
        productId: productId,
        page: 1,
        limit: 5,
      } satisfies IShoppingMallReview.IRequest,
    },
  );
  typia.assert(paginatedReviews);
  TestValidator.equals(
    "pagination limit respected",
    paginatedReviews.pagination.limit,
    5,
  );
  TestValidator.equals(
    "pagination current page is 1",
    paginatedReviews.pagination.current,
    1,
  );
  TestValidator.predicate(
    "data length does not exceed limit",
    paginatedReviews.data.length <= 5,
  );
  // 7. Test filtering by customerId
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const customerFilteredReviews =
    await api.functional.shoppingMall.reviews.index(customerConnection, {
      body: {
        customerId: customerId,
        page: 1,
        limit: 20,
      } satisfies IShoppingMallReview.IRequest,
    });
  typia.assert(customerFilteredReviews);
  TestValidator.predicate(
    "customer filter returns valid response",
    customerFilteredReviews.pagination.pages >= 0,
  );
  // 8. Test all filters combined
  const allFiltersReviews = await api.functional.shoppingMall.reviews.index(
    customerConnection,
    {
      body: {
        productId: productId,
        customerId: customerId,
        rating: 5,
        startDate: startDate.toISOString(),
        endDate: endDate.toISOString(),
        search: "great",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallReview.IRequest,
    },
  );
  typia.assert(allFiltersReviews);
  TestValidator.equals(
    "all filters combined returns valid pagination",
    allFiltersReviews.pagination.current,
    1,
  );
  TestValidator.equals(
    "all filters combined respects limit",
    allFiltersReviews.pagination.limit,
    10,
  );
  // 9. Test different page number
  const page2Reviews = await api.functional.shoppingMall.reviews.index(
    customerConnection,
    {
      body: {
        productId: productId,
        page: 2,
        limit: 10,
      } satisfies IShoppingMallReview.IRequest,
    },
  );
  typia.assert(page2Reviews);
  TestValidator.equals(
    "page 2 returns correct current page",
    page2Reviews.pagination.current,
    2,
  );
  // 10. Test different rating values
  for (const rating of [1, 2, 3, 4, 5] as const) {
    const ratingFiltered = await api.functional.shoppingMall.reviews.index(
      customerConnection,
      {
        body: {
          rating: rating,
          page: 1,
          limit: 20,
        } satisfies IShoppingMallReview.IRequest,
      },
    );
    typia.assert(ratingFiltered);
    TestValidator.equals(
      `rating ${rating} filter returns valid response`,
      ratingFiltered.pagination.current,
      1,
    );
  }
  // 11. Test limit boundary values
  const maxLimitReviews = await api.functional.shoppingMall.reviews.index(
    customerConnection,
    {
      body: {
        limit: 100,
        page: 1,
      } satisfies IShoppingMallReview.IRequest,
    },
  );
  typia.assert(maxLimitReviews);
  TestValidator.equals(
    "max limit (100) is accepted",
    maxLimitReviews.pagination.limit,
    100,
  );
  const minLimitReviews = await api.functional.shoppingMall.reviews.index(
    customerConnection,
    {
      body: {
        limit: 1,
        page: 1,
      } satisfies IShoppingMallReview.IRequest,
    },
  );
  typia.assert(minLimitReviews);
  TestValidator.equals(
    "min limit (1) is accepted",
    minLimitReviews.pagination.limit,
    1,
  );
  // 12. Verify response structure for returned reviews
  const structureTestReviews = await api.functional.shoppingMall.reviews.index(
    customerConnection,
    {
      body: {
        page: 1,
        limit: 5,
      } satisfies IShoppingMallReview.IRequest,
    },
  );
  typia.assert(structureTestReviews);
  if (structureTestReviews.data.length > 0) {
    const firstReview = structureTestReviews.data[0];
    TestValidator.predicate(
      "review has valid UUID id",
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
        firstReview.id,
      ),
    );
    TestValidator.predicate(
      "review has valid rating (1-5)",
      firstReview.rating >= 1 && firstReview.rating <= 5,
    );
    TestValidator.predicate(
      "review has valid customer",
      firstReview.customer.id !== undefined,
    );
    TestValidator.predicate(
      "review has valid orderItem",
      firstReview.orderItem.id !== undefined,
    );
    TestValidator.predicate(
      "review has valid created_at",
      firstReview.created_at !== undefined,
    );
    TestValidator.predicate(
      "review has valid updated_at",
      firstReview.updated_at !== undefined,
