  for (const snapshot of dateRangeResult.data) {
    const snapshotDate = new Date(snapshot.createdAt);
    TestValidator.predicate(
      `snapshot ${snapshot.id} within date range`,
      snapshotDate >= oneWeekAgo && snapshotDate <= now,
    );
