  TestValidator.predicate(
    "variant snapshot exists",
    retrievedRefundRequest.orderItem.variantSnapshot !== null,
  );
  TestValidator.predicate(
    "quantity is positive",
    retrievedRefundRequest.orderItem.quantity > 0,
  );
  TestValidator.predicate(
