/**
 * Test refund snapshot immutability verification.
 *
 * This test verifies that refund request snapshots are immutable and preserve
 * the exact state of the refund request at the time of seller response.
 *
 * Workflow:
 * 1. Register and authenticate seller and customer accounts
 * 2. Customer adds product to cart and places order
 * 3. Seller ships the order
 * 4. Customer confirms delivery
 * 5. Customer creates refund request
 * 6. Seller responds to refund request (creates snapshot)
 * 7. Verify the refund request status was updated correctly
 *
 * Note: Full snapshot immutability verification requires a snapshot list endpoint
 * which is not available in the current API. This test verifies the refund
 * request workflow that triggers snapshot creation.
 */
export async function test_api_refund_snapshot_immutability_verification(
  connection: api.IConnection,
): Promise<void> {
  // 1. Setup: Register and authenticate seller
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      shop_name: RandomGenerator.name(2),
    },
  });
  typia.assert(sellerAuth);
  // 2. Setup: Register and authenticate customer
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {},
  });
  typia.assert(customerAuth);
  // 3. Customer adds product variant to cart
  const cartItem =
    await generate_random_shopping_mall_customer_customers_me_cart_items_create(
      customerConnection,
      {},
    );
  typia.assert(cartItem);
  // 4. Customer places order from cart
  const order =
    await generate_random_shopping_mall_customer_customers_me_orders_create(
      customerConnection,
      {},
    );
  typia.assert(order);
  // 5. Seller creates shipment for order items
  const shipment =
    await generate_random_shopping_mall_seller_sellers_me_shipments_create(
      sellerConnection,
      {},
    );
  typia.assert(shipment);
  // 6. Customer confirms delivery to enable refund window
  const confirmedShipment =
    await api.functional.shoppingMall.customer.shipments.confirm_delivery.confirmDelivery(
      customerConnection,
      {
        shipmentId: shipment.id,
      },
    );
  typia.assert(confirmedShipment);
  // 7. Customer creates refund request for delivered item
  const refundRequest =
    await generate_random_shopping_mall_customer_refund_requests_create(
      customerConnection,
      {},
    );
  typia.assert(refundRequest);
  // Record original refund reason for later verification
  const originalReason = refundRequest.reason;
  const originalStatus = refundRequest.status;
  // Verify initial status is pending
  TestValidator.equals(
    "initial refund request status is pending",
    originalStatus,
    "pending",
  );
  // 8. Seller responds to refund request (approve) to trigger snapshot creation
  const updatedRefundRequest =
    await api.functional.shoppingMall.seller.refund_requests.update(
      sellerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          status: "approved",
        } satisfies IShoppingMallRefundRequest.IUpdate,
      },
    );
  typia.assert(updatedRefundRequest);
  // 9. Verify the refund request status was updated
  TestValidator.equals(
    "refund request status updated to approved",
    updatedRefundRequest.status,
    "approved",
  );
  // 10. Verify the refund reason remains unchanged (immutability of reason)
  TestValidator.equals(
    "refund reason remains unchanged after approval",
    updatedRefundRequest.reason,
    originalReason,
  );
  // 11. Verify responded_at timestamp is set
  TestValidator.predicate(
    "responded_at timestamp is set after seller response",
    updatedRefundRequest.respondedAt !== null,
  );
  // 12. Verify requested_at timestamp remains unchanged
  TestValidator.equals(
    "requested_at timestamp remains unchanged",
    updatedRefundRequest.requestedAt,
    refundRequest.requestedAt,
  );
  // 13. Verify the order item status was updated to refunded
  TestValidator.equals(
    "order item status updated to refunded",
    updatedRefundRequest.orderItem.status,
    "refunded",
  );
  // Note: Full snapshot immutability verification would require retrieving
  // the snapshot from GET /refund-requests/{id}/snapshots/{snapshotId},
  // but we cannot discover the snapshot ID without a list endpoint.
  // The snapshot is created server-side when the seller responds,
  // and its immutability is enforced by the database design.
}

