  // 2. Call API with empty body (use defaults: page=1, limit=20)
  const response =
    await api.functional.shoppingMall.admin.adminPromotionRequests.index(
      adminConnection,
      {
        body: {} satisfies IShoppingMallAdminPromotionRequest.IRequest,
