    props.body.sort === "submitted_at"
      ? { submitted_at: props.body.order ?? "desc" }
      : props.body.sort === "responded_at"
        ? { responded_at: props.body.order ?? "desc" }
        : props.body.sort === "created_at"
          ? { created_at: props.body.order ?? "desc" }
          : ({
              submitted_at: "desc",
