import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function putShoppingMallAdminSellerApprovalRequestsRequestId(props: {
  admin: AdminPayload;
  requestId: string & tags.Format<"uuid">;
  body: IShoppingMallSellerApprovalRequest.IUpdate;
}): Promise<IShoppingMallSellerApprovalRequest> {
  // Fetch the seller approval request
  const request =
    await MyGlobal.prisma.shopping_mall_seller_approval_requests.findUniqueOrThrow(
      {
        where: {
          id: props.requestId,
          deleted_at: null,
        },
        select: {
          id: true,
          shopping_mall_seller_id: true,
          reason: true,
          status: true,
          submitted_at: true,
          responded_at: true,
          created_at: true,
          updated_at: true,
          deleted_at: true,
        },
      },
    );
  // Validate current state - must be pending
  if (request.status !== "pending") {
    throw new HttpException("Request already responded to", 409);
  }
  // Validate input - rejection reason required when rejecting
  if (
    props.body.status === "rejected" &&
    (!props.body.rejection_reason ||
      props.body.rejection_reason.trim().length === 0)
  ) {
    throw new HttpException("Rejection reason is required when rejecting", 400);
  }
  const now = new Date();
  // Create snapshot before updating
  await MyGlobal.prisma.shopping_mall_seller_approval_snapshots.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_seller_approval_request_id: request.id,
      snapshot_data: JSON.stringify({
        seller_id: request.shopping_mall_seller_id,
        reason: request.reason,
        status: request.status,
        submitted_at: request.submitted_at.toISOString(),
        responded_at: request.responded_at?.toISOString() ?? null,
      }),
      created_at: now,
    },
  });
  // Update the approval request
  await MyGlobal.prisma.shopping_mall_seller_approval_requests.update({
    where: {
      id: props.requestId,
    },
    data: {
      status: props.body.status,
      responded_at: now,
      updated_at: now,
    },
  });
  // Update seller profile
  await MyGlobal.prisma.shopping_mall_sellers.update({
    where: {
      id: request.shopping_mall_seller_id,
    },
    data: {
      approval_status: props.body.status,
      rejection_reason:
        props.body.status === "rejected" ? props.body.rejection_reason : null,
      updated_at: now,
    },
  });
  // Fetch and return the updated request with seller relation
  const finalRequest =
    await MyGlobal.prisma.shopping_mall_seller_approval_requests.findUniqueOrThrow(
      {
        where: {
          id: props.requestId,
        },
        ...ShoppingMallSellerApprovalRequestTransformer.select(),
      },
    );
  return await ShoppingMallSellerApprovalRequestTransformer.transform(
    finalRequest,
  );
}

