import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { ShoppingMallAdminPromotionRequestTransformer } from "../transformers/ShoppingMallAdminPromotionRequestTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function putShoppingMallAdminAdminPromotionRequestsRequestId(props: {
  admin: AdminPayload;
  requestId: string & tags.Format<"uuid">;
  body: IShoppingMallAdminPromotionRequest.IUpdate;
}): Promise<IShoppingMallAdminPromotionRequest> {
  // Verify the responding admin is a super administrator
  const respondingAdmin = await MyGlobal.prisma.shopping_mall_admins.findUnique(
    {
      where: {
        id: props.admin.id,
        deleted_at: null,
      },
      select: {
        id: true,
        grade: true,
        status: true,
      },
    },
  );
  if (respondingAdmin === null) {
    throw new HttpException("You're not enrolled", 403);
  }
  if (respondingAdmin.grade !== "super") {
    throw new HttpException(
      "Only super administrators can approve or reject promotion requests",
      403,
    );
  }
  if (respondingAdmin.status !== "active") {
    throw new HttpException("Your account is not active", 403);
  }
  // Find the promotion request with full details needed for snapshot
  const request =
    await MyGlobal.prisma.shopping_mall_admin_promotion_requests.findUnique({
      where: {
        id: props.requestId,
        deleted_at: null,
      },
      select: {
        id: true,
        shopping_mall_admin_id: true,
        status: true,
        reason: true,
        submitted_at: true,
      },
    });
  if (request === null) {
    throw new HttpException("Promotion request not found", 404);
  }
  // Validate the request is in pending status
  if (request.status !== "pending") {
    throw new HttpException("Promotion request is not in pending status", 409);
  }
  // Validate the new status
  if (props.body.status === undefined) {
    throw new HttpException("Status must be provided", 400);
  }
  const newStatus = props.body.status;
  if (newStatus !== "approved" && newStatus !== "rejected") {
    throw new HttpException("Status must be 'approved' or 'rejected'", 400);
  }
  // Perform the update in a transaction
  const now = new Date();
  const nowIso = now.toISOString();
  await MyGlobal.prisma.$transaction(async (tx) => {
    // Update the promotion request
    await tx.shopping_mall_admin_promotion_requests.update({
      where: { id: props.requestId },
      data: {
        status: newStatus,
        responded_at: now,
        updated_at: now,
      },
    });
    // Create a snapshot for audit trail
    await tx.shopping_mall_admin_promotion_snapshots.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        shopping_mall_admin_promotion_request_id: props.requestId,
        user_id: request.shopping_mall_admin_id,
        reason: request.reason,
        status: newStatus,
        submitted_at: request.submitted_at,
        responded_at: now,
        created_at: now,
      },
    });
    // If approved, grant regular admin status to the requesting user
    if (newStatus === "approved") {
      await tx.shopping_mall_admins.update({
        where: { id: request.shopping_mall_admin_id },
        data: {
          grade: "regular",
          updated_at: now,
        },
      });
    }
  });
  // Return the updated promotion request
  const updatedRequest =
    await MyGlobal.prisma.shopping_mall_admin_promotion_requests.findUniqueOrThrow(
      {
        where: { id: props.requestId },
        ...ShoppingMallAdminPromotionRequestTransformer.select(),
      },
    );
  return await ShoppingMallAdminPromotionRequestTransformer.transform(
    updatedRequest,
  );
}

