      },
    }),
    ...(props.body.delivered_at_to && {
      delivered_at: {
        lte: new Date(props.body.delivered_at_to),
      },
    }),
    ...(props.body.tracking_carrier && {
      tracking_carrier: {
        contains: props.body.tracking_carrier,
        mode: "insensitive",
