export async function postShoppingMallAdminCustomersBulkBan(props: {
  admin: AdminPayload;
  body: IShoppingMallCustomerBulkBan.ICreate;
}): Promise<IShoppingMallCustomerBulkBan.IResult> {
  const results: IShoppingMallCustomerBulkBan.IResultItem[] = [];
  let successCount = 0;
  let failureCount = 0;
  let skippedCount = 0;
  for (const customerId of props.body.customerIds) {
    try {
      const customer = await MyGlobal.prisma.shopping_mall_customers.findUnique(
        {
          where: {
            id: customerId,
          },
          select: {
            id: true,
            status: true,
          },
        },
      );
      if (customer === null) {
        results.push({
          customerId: customerId,
          status: "failed",
          errorMessage: "customer not found",
        } satisfies IShoppingMallCustomerBulkBan.IResultItem);
        failureCount++;
        continue;
      }
      if (customer.status === "banned") {
        results.push({
          customerId: customerId,
          status: "skipped",
          errorMessage: null,
        } satisfies IShoppingMallCustomerBulkBan.IResultItem);
        skippedCount++;
        continue;
      }
      await MyGlobal.prisma.shopping_mall_customers.update({
        where: {
          id: customerId,
        },
        data: {
          status: "banned",
          updated_at: new Date(),
        },
      });
      results.push({
        customerId: customerId,
        status: "success",
        errorMessage: null,
      } satisfies IShoppingMallCustomerBulkBan.IResultItem);
      successCount++;
    } catch (error) {
      results.push({
        customerId: customerId,
        status: "failed",
        errorMessage: error instanceof Error ? error.message : "unknown error",
      } satisfies IShoppingMallCustomerBulkBan.IResultItem);
      failureCount++;
    }
  }
  return {
    successCount: successCount,
    failureCount: failureCount,
    skippedCount: skippedCount,
    results: results,
  } satisfies IShoppingMallCustomerBulkBan.IResult;
}

