@Controller("/shoppingMall/admin/categories")
export class ShoppingmallAdminCategoriesController {
  /**
   * Create a new product category for organizing products in the shopping mall platform.
   *
   * This operation allows administrators to create new categories that serve as the primary organizational structure for product discovery. Categories support a hierarchical structure with one level of nesting, enabling both top-level categories and subcategories for more granular product classification.
   *
   * Categories are managed exclusively by platform administrators. When creating a category, administrators can specify a name (required), an optional description providing additional context, and optionally assign a parent category to create a subcategory. The system enforces the one-level nesting constraint, preventing subcategories from having their own subcategories.
   *
   * Each category receives a unique identifier upon creation and is immediately available for product assignment. Categories with the same name can exist under different parent categories, but duplicate names are not allowed within the same parent scope. Deleted categories are soft-deleted and remain in the system for audit purposes.
   *
   * Related operations include: GET /categories to list all categories, PUT /categories/{categoryId} to update an existing category, and DELETE /categories/{categoryId} to remove a category. Products can be assigned to categories through the product creation and update operations.
   *
   * @param connection
   * @param body Category creation data including name, optional description, and optional parent category reference
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Create a new category record in the shopping_mall_categories table.
   *
   * **Service Layer Logic**:
   * 1. Verify the authenticated user has administrator role (admin or super_admin grade)
   * 2. Validate request body: name is required, description is optional, parent_id is optional
   * 3. If parent_id is provided, verify it exists and is not deleted (deleted_at is null)
   * 4. Enforce one-level nesting constraint: if parent_id is provided, verify that parent category's own parent_id is null (parent cannot be a subcategory)
   * 5. Check unique constraint: ensure no existing category with same parent_id and name combination exists
   * 6. Generate UUID for new category id
   * 7. Set created_at and updated_at to current timestamp
   * 8. Set deleted_at to null (active category)
   * 9. Insert record into shopping_mall_categories table
   * 10. Return created category with all fields including generated id
   *
   * **Database Queries**:
   * - SELECT FROM shopping_mall_categories WHERE id = ? AND deleted_at IS NULL (verify parent exists)
   * - SELECT FROM shopping_mall_categories WHERE parent_id = ? AND name = ? AND deleted_at IS NULL (check uniqueness)
   * - INSERT INTO shopping_mall_categories (id, parent_id, name, description, created_at, updated_at, deleted_at) VALUES (?, ?, ?, ?, ?, ?, NULL)
   *
   * **Validation Rules**:
   * - Name: required, non-empty string, unique within parent scope
   * - Description: optional, nullable string
   * - Parent_id: optional, valid UUID, must reference existing non-deleted category, parent must be top-level (parent_id is null)
   *
   * **Error Handling**:
   * - Return 401 if user is not authenticated
   * - Return 403 if user is not an administrator
   * - Return 400 if name is missing or empty
   * - Return 400 if parent_id references non-existent category
   * - Return 400 if parent_id references deleted category
   * - Return 400 if parent_id references a subcategory (violates one-level nesting)
   * - Return 409 if category with same name already exists under same parent
   *
   * **Edge Cases**:
   * - Creating top-level category: parent_id is null
   * - Creating subcategory: parent_id references existing top-level category
   * - Duplicate name detection respects parent_id scope (same name allowed under different parents)
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @AdminAuth()
    admin: AdminPayload,
    @TypedBody()
    body: IShoppingMallCategory.ICreate,
  ): Promise<IShoppingMallCategory> {
    try {
      return await postShoppingMallAdminCategories({
        admin,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Delete a category from the shopping mall platform. This operation is exclusively available to administrators.
   *
   * When a category is deleted, the system performs a soft deletion by setting the deleted_at timestamp, which removes the category from all active listings while preserving the data for audit purposes. All products that were assigned to the deleted category are automatically moved to an uncategorized state (their category_id is set to null), ensuring no product data is lost.
   *
   * If the deleted category has subcategories, those subcategories are also soft deleted as part of the cascade operation. This maintains the integrity of the category hierarchy and prevents orphaned subcategories from remaining in the system.
